let h = 2.5;
let secant = null;
let Q = null;
let label = null;

function lineThrough(m) {
  const x0 = -0.8, x1 = 5;
  const y0 = f(a) + m * (x0 - a);
  const y1 = f(a) + m * (x1 - a);
  const clamp = (x, y) => {
    return [x, y];
  };
  // clip to y range [-1,5]
  let xs = x0, xe = x1;
  if (Math.abs(m) > 1e-9) {
    const xa = a + (-1 - f(a)) / m;
    const xb = a + (5 - f(a)) / m;
    const lo = Math.min(xa, xb), hi = Math.max(xa, xb);
    xs = Math.max(x0, lo);
    xe = Math.min(x1, hi);
  }
  const ys = f(a) + m * (xs - a);
  const ye = f(a) + m * (xe - a);
  return [axes.c2p(xs, ys), axes.c2p(xe, ye)];
}

